script.text:
			
function active$VoucherFilter$(sender) {
	sender.add_onResponseComplete(on$Filter$ResponseComplete);
	f.setReferenceKeyFilter('ma_hd');
}
function close$VoucherFilter$(sender) {try {sender.remove_onResponseComplete(on$Filter$ResponseComplete);} catch (ex) {}}
function onChange$z56$Filter$nh_vv1(o){
	var f = o.parentForm;
	f.setReferenceKeyFilter('ma_hd');
}

function on$Filter$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'Checking':
			var k = new Array();
			var g = f.grid;
			g._ma_hd = f.getItemValue('ma_hd'), g._nh_vv1 = f.getItemValue('nh_vv1'), g._kieu_xem = f.getItemValue('kieu_xem');
			if($func.trim(g._ma_hd) != '') Array.add(k, {Name: 'ma_hd', Opr: 'like', Value: g._ma_hd + '%', Type: 'String', Ignore: false});			if($func.trim(g._nh_vv1) != '') Array.add(k, {Name: 'nh_vv1', Opr: 'like', Value: g._nh_vv1 + '%', Type: 'String', Ignore: false});
			if($func.trim(g._kieu_xem) != '*') Array.add(k, {Name: 'cho_xu_ly', Opr: '=', Value: g._kieu_xem, Type: 'String', Ignore: false});
			
			g.set_externalKey(k);
			g._alterTitle = [null, [['%s', '', true]]];
			break;
		default:
			break;
	}
}
